              'value': cookie.value,
              'domain': cookie.domain,
              'path': cookie.path,
              'expires': expiryTime,
              'secure': cookie.secure,
              'httpOnly': true,
              'maxAge': cookie.maxAge, // Thêm max-age nếu có
