      leading: BasicShimmerContainer(Size(50, 50)),
      title: BasicShimmerContainer(Size(90, 20)),
      subtitle: BasicShimmerContainer(Size(40, 15)),
      trailing: BasicShimmerContainer(Size(50, 20)),
    );
  }
}

