                                  addToPlaylistController.changePlaylistType),
                          Text("Piped".tr),
                        ],
                      ),
                      const SizedBox(
                        width: 15,
                      ),
                      Row(
                        children: [
                          Radio(
                              value: "local",
                              // ignore: deprecated_member_use
                              groupValue:
                                  addToPlaylistController.playlistType.value,
                              // ignore: deprecated_member_use
                              onChanged:
                                  addToPlaylistController.changePlaylistType),
                          Text("local".tr),
