    for (final key in possibleKeys) {
      final value = config[key]?.toString();
      if (value != null && value.isNotEmpty) {
        // Xóa ký tự | và validate format
        final cleanValue =
            value.replaceAll('|', '').replaceAll('||', '').trim();
