            'secure': secure ?? true,
            'httpOnly': httpOnly ?? true,
            'source': 'response_headers',
          };
        }
      }

      if (cookieMap.isNotEmpty) {
        await saveYouTubeCookies(cookieMap);
        printINFO('Saved ${cookieMap.length} cookies from response headers');
